#!/usr/bin/env python3
"""
Emit the co-initialisation include files from ONE power-up vector.

  work/deposit_rtl.vh   applied to the RTL instance
  work/deposit_gate.vh  applied to the gate instance
  work/probe.vh         concatenations + signature for lockstep comparison

The SAME bit, identified by index, reaches both models.  That is the whole
mechanism -- not that the state is determinate, but that it is SHARED.

usage: gen_deposit.py <map.json> <mode> [seed] [--constrain PATH=VALUE ...]
       mode = x | zeros | ones | random
"""
import json, sys, random, hashlib, os

mapf, mode = sys.argv[1], sys.argv[2]
rest = sys.argv[3:]
seed = int(rest[0]) if rest and rest[0].isdigit() else 1
cons = {}
for i, a in enumerate(rest):
    if a == '--constrain' and i + 1 < len(rest):
        k, v = rest[i+1].split('=')
        cons[k] = int(v, 0)

M = json.load(open(mapf))
els, RI, GI = M['elements'], M['rtl_inst'], M['gate_inst']
rnd = random.Random(seed)

def val(e):
    for k, v in cons.items():
        if e['rtl_path'].startswith(k):
            return v & 1
    if mode == 'x':      return None
    if mode == 'zeros':  return 0
    if mode == 'ones':   return 1
    return rnd.getrandbits(1)

os.makedirs('work', exist_ok=True)
hdr = ('// generated by gen_deposit.py  mode=%s seed=%d\n'
       '// provenance: %s  (%d state points)\n'
       '// DO NOT EDIT -- regenerate when the netlist changes\n'
       % (mode, seed, M['fingerprint']['report_sha'], M['fingerprint']['n_state']))

# Resettable points are established by the reset sequence itself; the vector
# supplies only the non-resettable state.  Depositing over resettable points
# after the reset flush would destroy the state reset just established.
# Mark them with "has_reset": true in the map (trivially derived from the
# netlist cell type) -- if absent, every point is treated as non-resettable.
dep = [e for e in els if not e.get('has_reset', False)]

with open('work/deposit_rtl.vh', 'w') as fr, open('work/deposit_gate.vh', 'w') as fg:
    fr.write(hdr); fg.write(hdr)
    for e in dep:
        v = val(e)
        lit = "1'bx" if v is None else "1'b%d" % v
        fr.write("  %s.%s = %s;\n" % (RI, e['rtl_path'], lit))
        fg.write("  %s.%s = %s;\n" % (GI, e['gate_path'], lit))

# probe: packed state of both models + a folded signature for cheap comparison
N = len(els)
with open('work/probe.vh', 'w') as f:
    f.write(hdr)
    f.write('localparam int NST = %d;\n' % N)
    f.write('wire [NST-1:0] rtl_state = {\n  ')
    f.write(',\n  '.join('%s.%s' % (RI, e['rtl_path']) for e in reversed(els)))
    f.write('};\n')
    f.write('wire [NST-1:0] gate_state = {\n  ')
    f.write(',\n  '.join('%s.%s' % (GI, e['gate_path']) for e in reversed(els)))
    f.write('};\n')
    f.write('''
// Per-cycle check is a single 4-state case-inequality over the packed state.
// It is one simulator operation and, unlike any hash folded from 2-state
// values, it distinguishes x from 0 -- which is the divergence class that
// matters most here.  Localisation scans bitwise only after a mismatch.
//
// For very large state, partition `rtl_state`/`gate_state` into chunks and
// compare chunk-wise so localisation only rescans the failing chunk.
''')
    f.write('function automatic string st_name(input int i);\n  case (i)\n')
    for e in els:
        f.write('    %d: return "%s";\n' % (e['idx'], e['rtl_path']))
    f.write('    default: return "?";\n  endcase\nendfunction\n')

print('wrote work/deposit_rtl.vh, work/deposit_gate.vh, work/probe.vh')
print('  state points compared : %d' % N)
print('  points deposited      : %d  (%d resettable points left to the reset sequence)'
      % (len(dep), N - len(dep)))
print('  mode=%s seed=%d' % (mode, seed))
if cons: print('constraints: %s' % cons)
